old_answers = {
    "供需求": "供大于求价格下降，供不应求价格上升",
    "通货膨胀": "钱变多物价上涨，货币购买力下降",
    "机会成本": "选择一种方案时放弃的其他方案中最大的价值",
    "二进制": "计算机用0和1表示数，逢二进一",
    "数据库": "数据库是结构化存储和管理数据的系统",
    "递归": "函数直接或间接调用自己（自己调用自己），把大问题拆成同类小问题",
    "面向对象": "面向对象把数据和操作封装成对象，支持继承多态",
}
for key, old in old_answers.items():
    print("processing:", key, flush=True)
    found = False
    for m in re.finditer(r'    "%s": "' % key, src):
        line_start = m.start()
        line_end = src.index("\n", line_start)
        line = src[line_start:line_end]
        if old in line:
            src = src[:line_start] + '    "%s": "%s",' % (key, ANSWERS[key]) + src[line_end:]
            found = True
            break
    assert found, f"old answer not found for {key}"

UPD = {
    "供需求": ['供求', '供需', '供大于求', '供需求', '供求关系', '供需关系', '供不应求', '价格由', '供需平衡', '为什么涨价', '为什么降价', '物以稀为贵'],
    "通货膨胀": ['通货膨胀', '通胀', '物价上涨', '钱不值钱', '通胀是', '购买力下降', '钱变多', '通胀率', '货币贬值', '为什么钱不值钱'],
    "机会成本": ['机会成本', '机会代价', '机会成本是', '放弃的', '选择成本', '最优选择', '次优', '时间成本', '决策成本'],
    "二进制": ['二进制', '什么是二进制', '计算机二进制', '二进制是', '0和1', '逢二进一', '二进制数', '字节', 'bit', '位和字节'],
    "数据库": ['什么是数据库', '数据库是什么', '数据库作用', '数据库', 'SQL', '数据表', 'MySQL', '数据库是', '增删改查', '关系型数据库'],
    "递归": ['什么是递归', '递归是什么', '递归算法', '递归', '递归是', '阶乘', '斐波那契', '调用自己', '递归函数', '终止条件', '汉诺塔'],
    "面向对象": ['面向对象', 'OOP', '类与对象', '面向对象是', '封装', '继承', '多态', '类和对象', '面向过程', '对象'],
}
for theme, lst in UPD.items():
    m = re.search(r'"%s":\s*\[[^\]]*\]' % theme, src)
    assert m, f"cluster anchor not found: {theme}"
    new = '"%s": [%s]' % (theme, ", ".join('"%s"' % t for t in lst))
    src = src[:m.start()] + new + src[m.end():]

